window.products.push({"id":826444,"name":"Wilton Skeleton Cake Pan","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/9133Mq4DTsL._AC_SL1500_.jpg","description":"Add spooky fun to your Halloween celebrations with this one-mix skeleton cake pan. You'll love how easy it is to make a cake this cute for your Halloween party - raised design in pan leaves indented areas that can be filled with white icing to easily make the skeleton's bones. Non-Stick surface means cakes will release easily for less breakage and quicker cleanup. Skeleton measures approx. 13 in. (33 cm) tall. Made in china.","images":["https://m.media-amazon.com/images/I/9133Mq4DTsL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Wilton","source_asin":"B00KIF525A","category_path":"Home & Kitchen"},"sku":"BM-826444","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00KIF525A","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00KIF525A","price_pending":true,"merchant_ready":false});
